export const getDestination = (slug: string) => destinations.find((d) => d.slug === slug);

export const destinationsByRegion: Record<Region, Destination[]> = {
  western: destinations.filter((d) => d.region === "western"),
  central: destinations.filter((d) => d.region === "central"),
  eastern: destinations.filter((d) => d.region === "eastern"),
};

export const featuredDestinations = destinations.filter((d) => d.featured);
